#!/bin/bash
# Fix Kotlin DSL build.gradle.kts generated by flutter create.
# Flutter 3.47.5 generates build.gradle.kts with Groovy syntax (readWithUTF8)
# which doesn't compile in Kotlin DSL. Replace with Kotlin-compatible readText.
cd android
sed -i "s/readWithUTF8(['\"]UTF-8['\"])/readText(Charsets.UTF_8)/g" build.gradle.kts
echo "Fixed build.gradle.kts"
